/**
 * Helper to get localized strings for a language code.
 * Falls back to English if the specific language is not found.
 */
export function getKioskStrings(langCode = 'en') {
  if (!langCode) return kioskStrings.en;
  const base = langCode.split('-')[0].toLowerCase();
  const rawStrings = kioskStrings[base] || kioskStrings.en;
  const modeStrings = MODE_LOCALIZATIONS[base] || MODE_LOCALIZATIONS.en;

  return {
    ...rawStrings,
    modernConsultation: rawStrings.modernConsultation || modeStrings.modernConsultation || MODE_LOCALIZATIONS.en.modernConsultation,
    modernConsultationDesc: rawStrings.modernConsultationDesc || modeStrings.modernConsultationDesc || MODE_LOCALIZATIONS.en.modernConsultationDesc,
    ayushConsultation: rawStrings.ayushConsultation || modeStrings.ayushConsultation || MODE_LOCALIZATIONS.en.ayushConsultation,
    ayushConsultationDesc: rawStrings.ayushConsultationDesc || modeStrings.ayushConsultationDesc || MODE_LOCALIZATIONS.en.ayushConsultationDesc,
    selectConsultationType: rawStrings.selectConsultationType || modeStrings.selectConsultationType || MODE_LOCALIZATIONS.en.selectConsultationType
  };
}

/**
 * Get localized phase metadata (title and subtitle) for a section key and language
 */
export function getLocalizedPhaseMeta(sectionKey, langCode = 'en') {
  const strings = getKioskStrings(langCode);
  const phase = strings.phases?.[sectionKey];
  if (phase) {
    return phase;
  }
  const knownTitles = {
    chief_complaint: 'Chief Complaint',
    hpi: 'History of Illness',
    extended_history: 'Medical History',
    ros: 'Review of Systems',
    dashavidha_pariksha: 'Dashavidha Pariksha',
    ahara_vihara: 'Ahara & Vihara',
    ayush: strings.ayushConsultation || 'AYUSH Assessment'
  };
  const title = knownTitles[sectionKey] || (sectionKey ? sectionKey.toUpperCase().replace(/_/g, ' ') : strings.intakeDesk);
  return {
    title,
    subtitle: strings.connectingEngine
  };
}
